/* CRUD routes for every entity. Generated by Chakram; the same shape for every app. */
import { Hono } from 'hono';
import { z } from 'zod';
import { entities, entityNames, type EntityName } from './schema.js';
import { requireRole, type Vars } from './auth.js';
import type { Store, ListQuery } from './store.js';

const listQuerySchema = z.object({
  sort: z.string().optional(),
  dir: z.enum(['asc', 'desc']).optional(),
  limit: z.coerce.number().int().min(1).max(500).optional(),
  offset: z.coerce.number().int().min(0).optional(),
});

function problem(issues: z.ZodError): { code: string; message: string; retryable: boolean; fields: Record<string, string> } {
  const fields: Record<string, string> = {};
  for (const issue of issues.issues) fields[issue.path.join('.') || '_'] = issue.message;
  return { code: 'validation', message: 'Some fields are invalid', retryable: false, fields };
}

async function refsExist(store: Store, orgId: string, entity: EntityName, data: Record<string, unknown>): Promise<string | null> {
  for (const [field, target] of Object.entries(entities[entity].refs as Record<string, EntityName>)) {
    const id = data[field];
    if (typeof id !== 'string') continue;
    if (!(await store.get(target, orgId, id))) return `${field}: no ${target} with id ${id}`;
  }
  return null;
}

export function entityRoutes(store: Store): Hono<{ Variables: Vars }> {
  const app = new Hono<{ Variables: Vars }>();
  for (const name of entityNames) {
    const { collection, schema } = entities[name];
    const read = requireRole(store, 'viewer');
    const write = requireRole(store, 'member');

    app.get(`/${collection}`, read, async (c) => {
      const parsed = listQuerySchema.safeParse(c.req.query());
      if (!parsed.success) return c.json(problem(parsed.error), 400);
      const filter: Record<string, string> = {};
      for (const [k, v] of Object.entries(c.req.query())) {
        if (!['sort', 'dir', 'limit', 'offset'].includes(k) && k in schema.shape) filter[k] = v;
      }
      const query: ListQuery = { ...parsed.data, filter };
      const result = await store.list(name, c.get('user').orgId, query);
      return c.json(result);
    });

    app.get(`/${collection}/:id`, read, async (c) => {
      const row = await store.get(name, c.get('user').orgId, c.req.param('id'));
      return row ? c.json(row) : c.json({ code: 'not_found', message: `${name} not found`, retryable: false }, 404);
    });

    app.post(`/${collection}`, write, async (c) => {
      const body = await c.req.json().catch(() => null);
      const parsed = schema.safeParse(body);
      if (!parsed.success) return c.json(problem(parsed.error), 400);
      const orgId = c.get('user').orgId;
      const missing = await refsExist(store, orgId, name, parsed.data);
      if (missing) return c.json({ code: 'validation', message: missing, retryable: false }, 400);
      const row = await store.create(name, orgId, parsed.data);
      return c.json(row, 201);
    });

    app.put(`/${collection}/:id`, write, async (c) => {
      const body = await c.req.json().catch(() => null);
      const parsed = schema.partial().safeParse(body);
      if (!parsed.success) return c.json(problem(parsed.error), 400);
      const orgId = c.get('user').orgId;
      const missing = await refsExist(store, orgId, name, parsed.data);
      if (missing) return c.json({ code: 'validation', message: missing, retryable: false }, 400);
      const row = await store.update(name, orgId, c.req.param('id'), parsed.data);
      return row ? c.json(row) : c.json({ code: 'not_found', message: `${name} not found`, retryable: false }, 404);
    });

    app.delete(`/${collection}/:id`, write, async (c) => {
      const ok = await store.remove(name, c.get('user').orgId, c.req.param('id'));
      return ok ? c.body(null, 204) : c.json({ code: 'not_found', message: `${name} not found`, retryable: false }, 404);
    });
  }
  return app;
}
